```c
// transform.c
#include "transform.h"
#include <stddef.h>
void transform_inplace(double* data, size_t n, double scale) {
    if (data == NULL || n == 0) return;
    for (size_t i = 0; i < n; ++i) {
        data[i] *= scale;
    }
}
```

```go
// transform.go
package transform
/*
#include "transform.h"
*/
import "C"
import "unsafe"

func TransformInPlace(data []float64, scale float64) error {
    if len(data) == 0 { return nil }
    C.transform_inplace((*C.double)(unsafe.Pointer(&data[0])), C.size_t(len(data)), C.double(scale))
    return nil
}
```

